    """
    Verifica se ci sono shared.
    """
    try:
        if isinstance(shared, list):
            shared_arguments = shared
        else:
            shared_arguments = shared.__shared_arguments__
        for idx, (args, kwargs) in enumerate(shared_arguments):
            arg_name = kwargs.get(
